"use client";
import { useState } from "react";

export default function TodoForm() {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [priority, setPriority] = useState<"low" | "medium" | "high" | "">("");
    function handleSubmit(e: React.FormEvent) {
  e.preventDefault();
  console.log({ name, description, dueDate, priority });
}
  return (
    <form onSubmit={handleSubmit} className="max-w-xl mx-auto mt-10 p-6 rounded-xl shadow-lg space-y-5">

      <h2 className="text-2xl font-bold mb-6">
        Add Todo
      </h2>

      
      <div>
        <label className="block mb-2">
          Name
        </label>

        <input
            type="text"
            placeholder="Enter todo name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="w-full border rounded-md p-2"
        />
      </div>

      
      <div>
        <label className="block mb-2">
          Description
        </label>

        <textarea
            placeholder="Enter todo description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="w-full border rounded-md p-2 min-h-24"
        />
      </div>

     
      <div>
        <label className="block mb-2">
          Due Date
        </label>

        <input
            type="date"
            value={dueDate}
            onChange={(e) => setDueDate(e.target.value)}
            className="w-full border rounded-md p-2"
        />
      </div>

    
      <div>
        <label className="block mb-2">
          Priority
        </label>

        <select
            value={priority}
            onChange={(e) => setPriority(e.target.value as "low" | "medium" | "high" | "")}
            className="w-full border rounded-md p-2 bg-white text-black"
            >
            <option value="">Select priority</option>
            <option value="low">Low</option>
            <option value="medium">Medium</option>
            <option value="high">High</option>
        </select>
      </div>

   
      <button
        type="submit"
        className="w-full rounded-md p-2 font-semibold bg-blue-600 text-white hover:bg-blue-700 transition"
        >
        Add Todo
    </button>

    </form>
  );
}